function makeValueCache() {
  var lastId = null;
  var lastValue = null;

  return function getValue(user) {
    if (lastValue !== null && user.id === lastId) return lastValue;
    lastId = user.id;
    lastValue = { user: user };
    return lastValue;
  };
}

var getValue = makeValueCache();
console.log(getValue({ id: 1 }) === getValue({ id: 1 }));
